import java.io.*;
import java.util.*;
import java.util.stream.IntStream;

public class Task {

    public static void main(String[] args) throws IOException {
        new Task().execute();
    }

    private PrintWriter writer;
    private Reader reader;

    private Task() throws IOException {
        try {
            reader = new Reader("input.txt");
            writer = new PrintWriter(new BufferedWriter(new FileWriter("output.txt")));
        } catch (IOException e) {
            reader = new Reader();
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        }
    }

    private void execute() throws IOException {
        int testCases = 1;
        for (int tc = 0; tc < testCases; tc++) {
            compute();
        }
        writer.flush();
        writer.close();
    }

    private static final int MOD = 1_000_000_007;

    private void compute() throws IOException {
        int n = reader.nextInt();
        int[][] dp = new int[2 * n][n + 1];
        dp[0][1] = 1;

        for (int step = 1; step < 2 * n; step++) {
            for (int pos = 0; pos <= n; pos++) {
                if (pos + 1 <= n) {
                    dp[step][pos + 1] = (dp[step][pos + 1] + dp[step - 1][pos]) % MOD;
                }
                if (pos - 1 >= 0) {
                    dp[step][pos - 1] = (dp[step][pos - 1] + dp[step - 1][pos]) % MOD;
                }
            }
        }

        int total = 0;
        for (int step = 2 * n - 2; step >= 0; step -= 2) {
            for (int pos = 1; pos <= n; pos += 2) {
                if (pos <= 2 * n - 1 - step) {
                    total = (total + dp[step][pos]) % MOD;
                }
            }
        }

        writer.print(total);
    }

    static class Pair implements Comparable<Pair> {
        int first, second;

        Pair(int first, int second) {
            this.first = first;
            this.second = second;
        }

        @Override
        public int compareTo(Pair other) {
            int cmp = Integer.compare(first, other.first);
            return cmp != 0 ? cmp : Integer.compare(second, other.second);
        }
    }

    static class Item {
        int x, y, z;

        Item(int x, int y, int z) {
            this.x = x;
            this.y = y;
            this.z = z;
        }
    }

    static class Reader {
        private BufferedReader bufferedReader;
        private StringTokenizer tokenizer;

        Reader(String filename) throws IOException {
            bufferedReader = new BufferedReader(new FileReader(filename));
        }

        Reader() throws IOException {
            bufferedReader = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(bufferedReader.readLine());
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        String nextLine() throws IOException {
            return bufferedReader.readLine();
        }

        int[] nextIntArray(int size) throws IOException {
            int[] array = new int[size];
            for (int i = 0; i < size; i++) {
                array[i] = nextInt();
            }
            return array;
        }

        ArrayList<Integer>[] nextGraph(int nodes, int edges) throws IOException {
            ArrayList<Integer>[] adjacency = new ArrayList[nodes];
            for (int i = 0; i < nodes; i++) {
                adjacency[i] = new ArrayList<>();
            }
            for (int i = 0; i < edges; i++) {
                int u = nextInt() - 1;
                int v = nextInt() - 1;
                adjacency[u].add(v);
                adjacency[v].add(u);
            }
            return adjacency;
        }
    }
}
